       wr_fifo_len_unsigned, wr_valid_internal)
    VARIABLE wr_valid : std_logic;
    VARIABLE reset_pending : std_logic;
    VARIABLE wr_addr_mod4KB_shift : unsigned(11 DOWNTO 0);
    VARIABLE cross_4KB_flag : std_logic;
    VARIABLE cross_4KB_split_len : unsigned(11 DOWNTO 0);
    VARIABLE cross_MaxBurst_flag : std_logic;
    VARIABLE split_len : unsigned(7 DOWNTO 0);
    VARIABLE awlen_reg_plus1 : unsigned(9 DOWNTO 0);
    VARIABLE last_burst_reg_temp : std_logic;
    VARIABLE addr_done_reg_temp : std_logic;
    VARIABLE add_temp : unsigned(31 DOWNTO 0);
  BEGIN
    last_burst_reg_temp := axi4_master_wr_last_burst_reg;
    addr_done_reg_temp := axi4_master_wr_addr_done_reg;
    axi4_master_wr_wr_astate_next <= axi4_master_wr_wr_astate;
    axi4_master_wr_wr_dstate_next <= axi4_master_wr_wr_dstate;
    axi4_master_wr_wr_len_reg_next <= axi4_master_wr_wr_len_reg;
    axi4_master_wr_wr_addr_reg_next <= axi4_master_wr_wr_addr_reg;
    axi4_master_wr_wr_awid_reg_next <= axi4_master_wr_wr_awid_reg;
    axi4_master_wr_data_done_reg_next <= axi4_master_wr_data_done_reg;
    axi4_master_wr_awlen_reg_next <= axi4_master_wr_awlen_reg;
    axi4_master_wr_burst_cnt_reg_next <= axi4_master_wr_burst_cnt_reg;
    axi4_master_wr_awvalid_reg_next <= axi4_master_wr_awvalid_reg;
    axi4_master_wr_awaddr_reg_next <= axi4_master_wr_awaddr_reg;
    axi4_master_wr_awid_reg_next <= axi4_master_wr_awid_reg;
    axi4_master_wr_wvalid_reg_next <= axi4_master_wr_wvalid_reg;
    axi4_master_wr_wlast_reg_next <= axi4_master_wr_wlast_reg;
    wr_valid := wr_valid_internal;
    reset_pending := soft_reset_pending;
    wr_complete_internal <= (axi4_master_wr_last_burst_reg AND axi4_master_wr_wlast_reg) AND axi4_master_wr_wvalid_reg;
    wr_addr_mod4KB_shift := SHIFT_RIGHT(axi4_master_wr_wr_addr_reg(11 DOWNTO 0), 2);
    add_temp := resize(wr_addr_mod4KB_shift, 32) + axi4_master_wr_wr_len_reg;
    IF add_temp > to_unsigned(1023, 32) THEN 
      cross_4KB_flag := '1';
    ELSE 
      cross_4KB_flag := '0';
    END IF;
    cross_4KB_split_len := to_unsigned(16#3FF#, 12) - wr_addr_mod4KB_shift;
    IF axi4_master_wr_wr_len_reg > to_unsigned(255, 32) THEN 
      cross_MaxBurst_flag := '1';
    ELSE 
      cross_MaxBurst_flag := '0';
    END IF;
    IF cross_4KB_split_len > to_unsigned(16#0FF#, 12) THEN 
      cross_4KB_split_len := to_unsigned(16#0FF#, 12);
    END IF;
    split_len := cross_4KB_split_len(7 DOWNTO 0);
    awlen_reg_plus1 := resize(axi4_master_wr_awlen_reg, 10) + to_unsigned(16#001#, 10);
    CASE axi4_master_wr_wr_astate IS
      WHEN "00000000" =>
        last_burst_reg_temp := '0';
        addr_done_reg_temp := '0';
        IF (wr_valid AND ( NOT reset_pending)) = '1' THEN 
          axi4_master_wr_wr_astate_next <= to_unsigned(16#01#, 8);
        END IF;
        axi4_master_wr_wr_len_reg_next <= wr_fifo_len_unsigned;
        axi4_master_wr_wr_addr_reg_next <= wr_fifo_addr_unsigned;
        axi4_master_wr_wr_awid_reg_next <= const_IDWidth;
      WHEN "00000001" =>
        addr_done_reg_temp := '0';
        IF axi4_master_wr_awvalid_reg = '1' AND (AXI4_Master_Activation_Data_Wr_AWREADY /= '0') THEN 
          axi4_master_wr_awvalid_reg_next <= '0';
          axi4_master_wr_wr_astate_next <= to_unsigned(16#03#, 8);
        ELSE 
          axi4_master_wr_awvalid_reg_next <= '1';
        END IF;
        axi4_master_wr_awaddr_reg_next <= axi4_master_wr_wr_addr_reg;
        axi4_master_wr_awid_reg_next <= axi4_master_wr_wr_awid_reg;
        IF cross_4KB_flag = '1' THEN 
          axi4_master_wr_awlen_reg_next <= split_len;
          last_burst_reg_temp := '0';
        ELSIF cross_MaxBurst_flag = '1' THEN 
          axi4_master_wr_awlen_reg_next <= to_unsigned(16#FF#, 8);
          last_burst_reg_temp := '0';
        ELSE 
          axi4_master_wr_awlen_reg_next <= axi4_master_wr_wr_len_reg(7 DOWNTO 0);
          last_burst_reg_temp := '1';
        END IF;
      WHEN "00000011" =>
        IF axi4_master_wr_data_done_reg = '1' THEN 
          IF axi4_master_wr_last_burst_reg = '1' THEN 
            axi4_master_wr_wr_astate_next <= to_unsigned(16#00#, 8);
          ELSE 
            axi4_master_wr_wr_astate_next <= to_unsigned(16#01#, 8);
          END IF;
          axi4_master_wr_wr_len_reg_next <= axi4_master_wr_wr_len_reg - resize(awlen_reg_plus1, 32);
          axi4_master_wr_wr_addr_reg_next <= axi4_master_wr_wr_addr_reg + resize(resize(awlen_reg_plus1, 11) sll 2, 32);
          addr_done_reg_temp := '1';
        END IF;
      WHEN OTHERS => 
        axi4_master_wr_wr_astate_next <= to_unsigned(16#00#, 8);
    END CASE;
    CASE axi4_master_wr_wr_dstate IS
      WHEN "00000000" =>
        wr_fifo_ack <= '0';
        wr_transfer <= '0';
        axi4_master_wr_data_done_reg_next <= '0';
        IF (wr_valid AND ( NOT reset_pending)) = '1' THEN 
          axi4_master_wr_wr_dstate_next <= to_unsigned(16#01#, 8);
        END IF;
        axi4_master_wr_wvalid_reg_next <= '0';
        axi4_master_wr_wlast_reg_next <= '0';
      WHEN "00000001" =>
        axi4_master_wr_wr_dstate_next <= to_unsigned(16#02#, 8);
        axi4_master_wr_data_done_reg_next <= '0';
        IF cross_4KB_flag = '1' THEN 
          axi4_master_wr_burst_cnt_reg_next <= split_len;
        ELSIF cross_MaxBurst_flag = '1' THEN 
          axi4_master_wr_burst_cnt_reg_next <= to_unsigned(16#FF#, 8);
        ELSE 
          axi4_master_wr_burst_cnt_reg_next <= axi4_master_wr_wr_len_reg(7 DOWNTO 0);
        END IF;
        wr_fifo_ack <= '0';
        wr_transfer <= '0';
      WHEN "00000010" =>
        IF (out_fifo_afull = '0') AND wr_valid = '1' THEN 
          axi4_master_wr_wvalid_reg_next <= '1';
          wr_fifo_ack <= '1';
          IF axi4_master_wr_burst_cnt_reg = to_unsigned(16#00#, 8) THEN 
            axi4_master_wr_wlast_reg_next <= '1';
            axi4_master_wr_wr_dstate_next <= to_unsigned(16#03#, 8);
            axi4_master_wr_data_done_reg_next <= '1';
          END IF;
          axi4_master_wr_burst_cnt_reg_next <= axi4_master_wr_burst_cnt_reg - to_unsigned(16#01#, 8);
        ELSE 
          axi4_master_wr_wvalid_reg_next <= '0';
          wr_fifo_ack <= '0';
        END IF;
        wr_transfer <= '1';
      WHEN "00000011" =>
        IF addr_done_reg_temp = '1' THEN 
          IF last_burst_reg_temp = '1' THEN 
            axi4_master_wr_wr_dstate_next <= to_unsigned(16#00#, 8);
          ELSE 
            axi4_master_wr_wr_dstate_next <= to_unsigned(16#01#, 8);
          END IF;
        END IF;
        axi4_master_wr_wvalid_reg_next <= '0';
        axi4_master_wr_wlast_reg_next <= '0';
        wr_fifo_ack <= '0';
        wr_transfer <= '0';
        axi4_master_wr_data_done_reg_next <= '1';
      WHEN OTHERS => 
        wr_fifo_ack <= '0';
        wr_transfer <= '0';
        axi4_master_wr_wr_dstate_next <= to_unsigned(16#00#, 8);
    END CASE;
    AXI4_Master_Activation_Data_Wr_AWVALID_1 <= axi4_master_wr_awvalid_reg;
    AXI4_Master_Activation_Data_Wr_AWADDR_tmp <= axi4_master_wr_awaddr_reg;
    AXI4_Master_Activation_Data_Wr_AWLEN_tmp <= axi4_master_wr_awlen_reg;
    AXI4_Master_Activation_Data_Wr_AWID_tmp <= axi4_master_wr_awid_reg;
    out_fifo_push <= axi4_master_wr_wvalid_reg;
    out_fifo_wlast <= axi4_master_wr_wlast_reg;
    axi4_master_wr_last_burst_reg_next <= last_burst_reg_temp;
    axi4_master_wr_addr_done_reg_next <= addr_done_reg_temp;
  END PROCESS axi4_master_wr_output;


  AXI4_Master_Activation_Data_Wr_AWID <= std_logic_vector(AXI4_Master_Activation_Data_Wr_AWID_tmp);

  AXI4_Master_Activation_Data_Wr_AWADDR <= std_logic_vector(AXI4_Master_Activation_Data_Wr_AWADDR_tmp);

  AXI4_Master_Activation_Data_Wr_AWLEN <= std_logic_vector(AXI4_Master_Activation_Data_Wr_AWLEN_tmp);

  const_awsize <= to_unsigned(16#1#, 3);

  AXI4_Master_Activation_Data_Wr_AWSIZE <= std_logic_vector(const_awsize);

  const_1_2 <= to_unsigned(16#1#, 2);

  AXI4_Master_Activation_Data_Wr_AWBURST <= std_logic_vector(const_1_2);

  const_0_1 <= '0';

  AXI4_Master_Activation_Data_Wr_AWLOCK <= const_0_1;

  const_3_4 <= to_unsigned(16#3#, 4);

  AXI4_Master_Activation_Data_Wr_AWCACHE <= std_logic_vector(const_3_4);

  const_0_3 <= to_unsigned(16#0#, 3);

  AXI4_Master_Activation_Data_Wr_AWPROT <= std_logic_vector(const_0_3);


  const_wstrb <= to_unsigned(16#3#, 2);

  AXI4_Master_Activation_Data_Wr_WSTRB <= std_logic_vector(const_wstrb);

  AXI4_Master_Activation_Data_Wr_WVALID <= wvalid_internal;

  AXI4_Master_Activation_Data_Wr_BREADY <= const_1_1;

  user_wr_ready <=  NOT wr_fifo_afull;

  user_wr_complete <= wr_complete_internal;

  aw_transfer <= AXI4_Master_Activation_Data_Wr_AWREADY AND AXI4_Master_Activation_Data_Wr_AWVALID_1;

  const_0_9 <= to_unsigned(16#000#, 9);

  const_1_9 <= to_unsigned(16#001#, 9);

  
  aw_transfer_len <= const_0_9 WHEN aw_transfer = '0' ELSE
      const_1_9;

  w_transfer <= const_1_1 AND AXI4_Master_Activation_Data_Wr_BVALID;

  
  w_transfer_len <= const_0_9 WHEN w_transfer = '0' ELSE
      const_1_9;

  accum_awlen_adder_add_cast <= signed(resize(aw_transfer_len, 32));
  accum_aw_len <= accum_awlen_adder_add_cast + accum_value;

  accum_wlen_adder_sub_cast <= signed(resize(w_transfer_len, 32));
  accum_w_len <= accum_aw_len - accum_wlen_adder_sub_cast;

  reg_accum_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      accum_value <= to_signed(0, 32);
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        accum_value <= accum_w_len;
      END IF;
    END IF;
  END PROCESS reg_accum_process;


  
  in_burst_axi4_master_activation_data_wr <= '1' WHEN accum_value > to_signed(0, 32) ELSE
      '0';

  AXI4_Master_Activation_Data_Wr_AWVALID <= AXI4_Master_Activation_Data_Wr_AWVALID_1;

  AXI4_Master_Activation_Data_Wr_WDATA <= AXI4_Master_Activation_Data_Wr_WDATA_tmp;

END rtl;

